abstract final class EnglishAdvancedB1FourToSix {
  static const lessons = <EnglishAdvancedLesson>[
    EnglishAdvancedLesson(level:'B1',unitNumber:1,number:4,title:"An Unexpected Internship",titleArabic:"تدريب عملي غير متوقع",storyTitle:"An Unexpected Internship",storyTitleArabic:"تدريب عملي غير متوقع",paragraphs:<String>["Huda arrived at a community radio station expecting to sort documents during her internship. Instead, the producer took her into the recording booth and explained how broadcasting equipment worked.","At the morning briefing, the presenter became ill. A sound technician asked Huda to adjust the headset and microphone stand while a guest agreed to extend the programme.","That afternoon, Huda read a short segment using studio headphones. She checked a written script, paused between important sentences and delivered the announcement clearly despite feeling nervous.","The producer thanked Huda and offered practical feedback. She realised that an unexpected task could help her discover a new skill, especially when colleagues offered patient support."],storyWords:<EnglishAdvancedWord>[EnglishAdvancedWord("radio station","محطة إذاعية"),EnglishAdvancedWord("recording booth","غرفة تسجيل"),EnglishAdvancedWord("producer","منتج برامج"),EnglishAdvancedWord("broadcasting equipment","معدات بث"),EnglishAdvancedWord("morning briefing","إحاطة صباحية"),EnglishAdvancedWord("presenter","مذيع"),EnglishAdvancedWord("sound technician","فني صوت"),EnglishAdvancedWord("headset","سماعة رأس"),EnglishAdvancedWord("microphone stand","حامل ميكروفون"),EnglishAdvancedWord("programme","برنامج إذاعي"),EnglishAdvancedWord("segment","فقرة برنامج"),EnglishAdvancedWord("studio headphones","سماعات استوديو")],extraWords:<EnglishAdvancedWord>[EnglishAdvancedWord("airtime","وقت البث"),EnglishAdvancedWord("broadcast signal","إشارة بث"),EnglishAdvancedWord("news bulletin","نشرة أخبار"),EnglishAdvancedWord("live transmission","بث مباشر"),EnglishAdvancedWord("interview outline","مخطط مقابلة"),EnglishAdvancedWord("audio mixer","جهاز مزج صوت"),EnglishAdvancedWord("sound levels","مستويات الصوت"),EnglishAdvancedWord("editing desk","منضدة تحرير"),EnglishAdvancedWord("voiceover","تعليق صوتي"),EnglishAdvancedWord("script revision","تنقيح النص"),EnglishAdvancedWord("rehearsal cue","إشارة تدريب"),EnglishAdvancedWord("recording session","جلسة تسجيل"),EnglishAdvancedWord("guest speaker","ضيف متحدث"),EnglishAdvancedWord("closing remarks","كلمات ختامية"),EnglishAdvancedWord("broadcast delay","تأخير البث"),EnglishAdvancedWord("studio control room","غرفة تحكم الاستوديو"),EnglishAdvancedWord("newsreader","قارئ الأخبار"),EnglishAdvancedWord("audio playback","تشغيل مقطع صوتي")],grammarTitle:"Present perfect for experiences",grammarArabic:"نستخدم المضارع التام لوصف خبرة حتى الآن دون وقت محدد: I have never presented a programme. وعندما نذكر وقتًا منتهيًا مثل yesterday نستخدم الماضي البسيط: I presented yesterday. الصيغة have/has + past participle.",grammarExamples:<String>["I have never spoken on the radio before.","Huda presented a short segment yesterday.","Have you ever worked in a recording studio?"],listening:"Good afternoon. Today's broadcast will begin twenty minutes later than planned because our regular presenter is unwell. The guest has agreed to answer additional questions about local music. Our trainee, Huda, will introduce the final segment. The phone-in competition has been moved to tomorrow morning, although the remaining shows will continue as advertised. All team members should consult the revised schedule before returning to the control room.",listeningQuestion:"Which part of today's broadcast moved to tomorrow?",listeningOptions:<String>["The guest interview","The phone-in competition","The final introduction"],listeningAnswer:1,readingQuestion:"Why did Huda have to introduce a segment?",readingOptions:<String>["The presenter was ill","The guest left early","Her manager was on holiday"],readingAnswer:0,writingCue:"The radio ____ helped Huda prepare her announcement.",writingAnswer:"producer"),
    EnglishAdvancedLesson(level:'B1',unitNumber:1,number:5,title:"The Neighborhood Petition",titleArabic:"عريضة الحي",storyTitle:"The Neighborhood Petition",storyTitleArabic:"عريضة الحي",paragraphs:<String>["The parents of Willow Street were concerned about a dangerous crossing near their school. Drivers ignored the speed limit, and children had trouble reaching the opposite pavement safely.","Leila collected signatures for a petition addressed to the local authority. Her doorstep survey asked residents about road safety, road markings and the possibility of a traffic island.","At a public meeting, parents using pushchairs explained their concerns. A transport officer said that a safety inspection was necessary before permanent changes could be approved.","After reviewing photographs and statements, the council promised temporary warning signs and brighter lamps. Leila understood that listening and respectful discussion could lead to practical improvements."],storyWords:<EnglishAdvancedWord>[EnglishAdvancedWord("dangerous crossing","خط عبور خطير"),EnglishAdvancedWord("speed limit","حد السرعة"),EnglishAdvancedWord("opposite pavement","الرصيف المقابل"),EnglishAdvancedWord("signatures","توقيعات"),EnglishAdvancedWord("petition","عريضة"),EnglishAdvancedWord("local authority","سلطة محلية"),EnglishAdvancedWord("road safety","سلامة الطرق"),EnglishAdvancedWord("doorstep survey","استبيان منازل"),EnglishAdvancedWord("road markings","علامات الطريق"),EnglishAdvancedWord("traffic island","جزيرة مرورية"),EnglishAdvancedWord("pushchairs","عربات أطفال"),EnglishAdvancedWord("safety inspection","فحص سلامة")],extraWords:<EnglishAdvancedWord>[EnglishAdvancedWord("zebra crossing","ممر مشاة مخطط"),EnglishAdvancedWord("pedestrian refuge","ملاذ للمشاة"),EnglishAdvancedWord("school zone","منطقة مدرسة"),EnglishAdvancedWord("traffic calming","تهدئة المرور"),EnglishAdvancedWord("road junction","تقاطع طرق"),EnglishAdvancedWord("warning sign","علامة تحذير"),EnglishAdvancedWord("streetlamp","مصباح شارع"),EnglishAdvancedWord("curb ramp","منحدر الرصيف"),EnglishAdvancedWord("crosswalk visibility","وضوح ممر المشاة"),EnglishAdvancedWord("vehicle speed","سرعة المركبة"),EnglishAdvancedWord("neighborhood notice","إعلان الحي"),EnglishAdvancedWord("resident association","جمعية سكان"),EnglishAdvancedWord("written endorsement","تأييد مكتوب"),EnglishAdvancedWord("public hearing","جلسة استماع عامة"),EnglishAdvancedWord("accident prevention","منع الحوادث"),EnglishAdvancedWord("signal timing","توقيت الإشارة"),EnglishAdvancedWord("temporary barrier","حاجز مؤقت"),EnglishAdvancedWord("roadside hazard","خطر بجانب الطريق")],grammarTitle:"Defining relative clauses",grammarArabic:"نستخدم who لوصف الناس وthat أو which لتحديد الأشياء: The parent who signed the petition lives nearby. The crossing that needs repairs is near the school. لا نضع فواصل حول جملة الصلة التعريفية.",grammarExamples:<String>["The residents who signed live nearby.","The crossing that needs repairs is outside the school.","The signs which warn drivers will be replaced."],listening:"Residents of Willow Street are invited to a road safety meeting on Thursday. Engineers will examine the school crossing, measure traffic speeds and review the request for a traffic island. Temporary warning signs will be placed beside the school before the inspection. The council has not promised a permanent crossing yet, because the final design depends on the measurements. Parents who have witnessed a dangerous incident should send a written statement before Friday evening.",listeningQuestion:"Why has the permanent crossing not yet been approved?",listeningOptions:<String>["The school has closed","Measurements are still required","The parents cancelled the petition"],listeningAnswer:1,readingQuestion:"What evidence helped the council understand the problem?",readingOptions:<String>["Photographs and statements","A new school timetable","A list of bus fares"],readingAnswer:0,writingCue:"Leila collected ____ from neighbors to support the petition.",writingAnswer:"signatures"),
    EnglishAdvancedLesson(level:'B1',unitNumber:1,number:6,title:"The Volunteer Interview",titleArabic:"مقابلة المتطوع",storyTitle:"The Volunteer Interview",storyTitleArabic:"مقابلة المتطوع",paragraphs:<String>["Samira applied to an animal rescue centre and received an invitation to a volunteer interview. She read the shelter guidelines because she had never cared for an injured dog.","The coordinator described daily responsibilities, including the adoption process, cleaning kennels and organising feeding schedules. Animals recovering from veterinary treatment needed extra patience and trained supervision.","During the interview, Samira was asked what she would do if a frightened puppy refused to move. She said she would wait and ask an animal-care worker for advice.","On her first shift, Samira prepared clean bedding and washed bowls. She saw that careful, quiet support helped frightened animals begin to trust the people around them."],storyWords:<EnglishAdvancedWord>[EnglishAdvancedWord("animal rescue centre","مركز إنقاذ حيوانات"),EnglishAdvancedWord("volunteer interview","مقابلة تطوع"),EnglishAdvancedWord("injured dog","كلب مصاب"),EnglishAdvancedWord("shelter guidelines","إرشادات الملجأ"),EnglishAdvancedWord("daily responsibilities","مسؤوليات يومية"),EnglishAdvancedWord("adoption process","إجراءات تبنٍ"),EnglishAdvancedWord("kennels","بيوت الكلاب"),EnglishAdvancedWord("feeding schedules","جداول الإطعام"),EnglishAdvancedWord("veterinary treatment","علاج بيطري"),EnglishAdvancedWord("frightened puppy","جرو خائف"),EnglishAdvancedWord("animal-care worker","عامل رعاية الحيوانات"),EnglishAdvancedWord("clean bedding","فراش نظيف")],extraWords:<EnglishAdvancedWord>[EnglishAdvancedWord("vaccination record","سجل تطعيم"),EnglishAdvancedWord("foster family","أسرة رعاية مؤقتة"),EnglishAdvancedWord("animal welfare","رفاه الحيوان"),EnglishAdvancedWord("rescue transport","نقل الإنقاذ"),EnglishAdvancedWord("walking leash","مقود مشي"),EnglishAdvancedWord("training reward","مكافأة تدريب"),EnglishAdvancedWord("health screening","فحص صحي"),EnglishAdvancedWord("behavioral observation","ملاحظة سلوكية"),EnglishAdvancedWord("shelter capacity","استيعاب الملجأ"),EnglishAdvancedWord("adoption application","طلب تبنٍ"),EnglishAdvancedWord("recovery enclosure","حظيرة نقاهة"),EnglishAdvancedWord("donated blankets","بطانيات متبرع بها"),EnglishAdvancedWord("feeding bowl","وعاء إطعام"),EnglishAdvancedWord("rescue hotline","خط إنقاذ"),EnglishAdvancedWord("animal handler","مدرب رعاية الحيوان"),EnglishAdvancedWord("aftercare plan","خطة رعاية لاحقة"),EnglishAdvancedWord("care rota","جدول مناوبات الرعاية"),EnglishAdvancedWord("volunteer induction","تعريف المتطوعين")],grammarTitle:"Second conditional for hypothetical situations",grammarArabic:"نستخدم الشرط الثاني لنتخيل موقفًا غير واقع الآن: If a puppy were frightened, I would wait quietly. الصيغة if + past simple ثم would + فعل أساسي. المعنى افتراضي وليس حدثًا وقع في الماضي.",grammarExamples:<String>["If a puppy were frightened, I would speak gently.","I would ask for help if I felt unsure.","If the shelter had more space, it could welcome more animals."],listening:"Thank you for applying to volunteer at our shelter. Each new helper attends a two-hour orientation before starting duties. For the first three shifts, an experienced animal handler will supervise volunteers. Please do not enter the recovery enclosure without permission, and never administer medicine unless you are authorised. If an animal seems frightened, give it enough space and ask for assistance. All feeding tasks must be recorded on the daily care sheet so that every animal receives the correct amount.",listeningQuestion:"What should a volunteer do if an animal is frightened?",listeningOptions:<String>["Move it immediately","Give it space and contact staff","Offer medicine without permission"],listeningAnswer:1,readingQuestion:"What mattered most in Samira's interview answer?",readingOptions:<String>["Working without training","Patience and safety","Adopting every animal"],readingAnswer:1,writingCue:"Samira learned about the animal ____ at the shelter.",writingAnswer:"adoption process")
  ];
}
